  STRUCT('all_ecommerce-cvr-global-2026q2-statista' AS benchmark_id, 'all_ecommerce' AS vertical, 'GLOBAL' AS region, 'cvr' AS metric_id, DATE '2026-04-01' AS period_start, DATE '2026-06-30' AS period_end, 'mean' AS stat, NUMERIC '0.013' AS value, CAST(NULL AS NUMERIC) AS value_low, CAST(NULL AS NUMERIC) AS value_high, CAST(NULL AS STRING) AS currency, 'Statista, Online shopping conversion rate worldwide, Q2 2026' AS source, 'https://www.statista.com/statistics/439576/global-e-commerce-conversion-rate/' AS source_url, DATE '2026-10-15' AS as_of, 'Share of visits to e-commerce websites worldwide that converted to a purchase, one quarter.' AS definition_note, 'Statista Research Department; underlying panel not named on the page.' AS sample_note, CAST('aggregator' AS STRING) AS note),
