  STRUCT('all_ecommerce-return_rate-cz-2607-ppl' AS benchmark_id, 'all_ecommerce' AS vertical, 'CZ' AS region, 'return_rate' AS metric_id, DATE '2026-07-25' AS period_start, DATE '2026-07-25' AS period_end, 'mean' AS stat, NUMERIC '0.1' AS value, CAST(NULL AS NUMERIC) AS value_low, CAST(NULL AS NUMERIC) AS value_high, CAST(NULL AS STRING) AS currency, 'Seznam Zpravy, op-ed by the CEO of PPL CZ (July 2026)' AS source, 'https://www.seznamzpravy.cz/clanek/311389' AS source_url, DATE '2026-10-15' AS as_of, 'Average share of e-shop purchases returned in the Czech Republic, \'long term around 10 %\'. No period given; period set to the publish date 2026-07-25. Fashion returns far more, consumables far less.' AS definition_note, 'Data not named by the author (PPL CZ, a carrier).' AS sample_note, CAST('carrier claim, rounded' AS STRING) AS note),
