  ]) AS s
) S
ON T.benchmark_id = S.benchmark_id
WHEN MATCHED AND T.entered_by = S.entered_by THEN UPDATE SET
  vertical = S.vertical, region = S.region, metric_id = S.metric_id,
  period_start = S.period_start, period_end = S.period_end, stat = S.stat,
  value = S.value, value_low = S.value_low, value_high = S.value_high, currency = S.currency,
  source = S.source, source_url = S.source_url, as_of = S.as_of,
  definition_note = S.definition_note, sample_note = S.sample_note, note = S.note,
  is_active = TRUE
WHEN NOT MATCHED THEN INSERT
  (benchmark_id, vertical, region, metric_id, period_start, period_end, stat, value,
   value_low, value_high, currency, source, source_url, as_of, definition_note, sample_note,
   note, is_active, entered_by, entered_at)
VALUES
  (S.benchmark_id, S.vertical, S.region, S.metric_id, S.period_start, S.period_end, S.stat, S.value,
   S.value_low, S.value_high, S.currency, S.source, S.source_url, S.as_of, S.definition_note, S.sample_note,
   S.note, TRUE, S.entered_by, CURRENT_TIMESTAMP());

